package kindergarten

import (
	"errors"
	"sort"
)

// Garden represents a kindergarten garden with two rows of cups
// assigned to children in alphabetical order.
type Garden struct {
	rows     [2]string
	children []string // sorted copy of the provided names
}

var plantNames = map[byte]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// NewGarden parses the diagram and returns a Garden.
func NewGarden(diagram string, children []string) (*Garden, error) {
	// The diagram must start with a newline followed by two rows.
	if len(diagram) < 2 || diagram[0] != '\n' {
		return nil, errors.New("diagram must start with a newline")
	}
	rest := diagram[1:]
	idx := indexByte(rest, '\n')
	if idx < 0 {
		return nil, errors.New("diagram must have two rows")
	}
	row1 := rest[:idx]
	row2 := rest[idx+1:]
	if idx+1 != len(rest) {
		return nil, errors.New("diagram must have exactly two rows")
	}
	if len(row1) != len(row2) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(row1)%2 != 0 {
		return nil, errors.New("diagram must have an even number of cups")
	}
	for i := 0; i < len(row1); i++ {
		if _, ok := plantNames[row1[i]]; !ok {
			return nil, errors.New("invalid cup code")
		}
		if _, ok := plantNames[row2[i]]; !ok {
			return nil, errors.New("invalid cup code")
		}
	}
	// Children
	if len(children) > len(row1)/2 {
		return nil, errors.New("too many children")
	}
	// Check for duplicates
	seen := make(map[string]bool, len(children))
	for _, c := range children {
		if seen[c] {
			return nil, errors.New("duplicate child name")
		}
		seen[c] = true
	}
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)
	return &Garden{rows: [2]string{row1, row2}, children: sorted}, nil
}

func (g *Garden) Plants(child string) ([]string, bool) {
	idx := sort.SearchStrings(g.children, child)
	if idx >= len(g.children) || g.children[idx] != child {
		return nil, false
	}
	off := 2 * idx
	return []string{
		plantNames[g.rows[0][off]],
		plantNames[g.rows[0][off+1]],
		plantNames[g.rows[1][off]],
		plantNames[g.rows[1][off+1]],
	}, true
}
```

